// Sidebar.jsx
import React from 'react';
import { Link } from 'react-router-dom';

const Sidebar = () => {
  return (
    <div style={styles.sidebar}>
      <h2 style={styles.title}>Navigation</h2>
      <nav>
        <ul style={styles.navList}>
          <li style={styles.navItem}>
            <Link to="/dashboard" style={styles.navLink}>Dashboard</Link>
          </li>
          <li style={styles.navItem}>
            <Link to="/updateFor" style={styles.navLink}>Updation Form</Link>
          </li>
          <li style={styles.navItem}>
            <button style={styles.logoutButton}>Logout</button>
          </li>
        </ul>
      </nav>
    </div>
  );
};

const styles = {
  sidebar: {
    width: '250px',
    height: '100%',
    backgroundColor: '#f4f4f4',
    padding: '20px',
    position: 'fixed',
    top: '0',
    left: '0',
    boxShadow: '2px 0 5px rgba(0,0,0,0.1)',
  },
  title: {
    margin: '0 0 20px 0',
  },
  navList: {
    listStyle: 'none',
    padding: '0',
    margin: '0',
  },
  navItem: {
    margin: '10px 0',
  },
  navLink: {
    textDecoration: 'none',
    color: '#333',
    fontSize: '18px',
  },
  logoutButton: {
    border: 'none',
    backgroundColor: '#f44336',
    color: '#fff',
    padding: '10px 20px',
    fontSize: '16px',
    cursor: 'pointer',
  },
};

export default Sidebar;
